[Thinking]
**Writing a TCP/IP server in C**

The user wants a code example for a TCP server in C without extra details. I’ll create a simple TCP server that covers socket creation, binding, listening, accepting connections, and handling clients by echoing messages. The server will likely be cross-platform, focusing on Linux/Unix, so I’ll ensure it has minimal error checking. Including IPv4 and IPv6 support using `getaddrinfo` could be useful, and I should keep the formatting concise while presenting a single code snippet with comments and brief compile instructions.**Creating a simple TCP server in C**

I’m going to write a TCP server code that uses `socket(AF_INET, SOCK_STREAM, 0)`, sets the `SO_REUSEADDR` option, binds to `INADDR_ANY`, and uses a port from `argv` or defaults to 8080. The server will listen with a backlog of 16 and loop to accept clients. For each client, I’ll print peer info and implement an echo loop for reading messages. I’ll include robust read/write handling and send options to avoid `SIGPIPE`. I'll keep the code concise and provide compile and run instructions clearly.
[/Thinking]

Below is a simple, portable TCP IPv4 echo server in C for Linux/Unix. It accepts multiple clients sequentially (one at a time). You can extend it to handle clients concurrently with threads or fork if needed.

Code (tcp_server.c):
#include <arpa/inet.h>
#include <errno.h>
#include <netinet/in.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <unistd.h>

#define BACKLOG 16
#define BUF_SIZE 4096
#define DEFAULT_PORT 8080

static ssize_t write_all(int fd, const void *buf, size_t len) {
    const char *p = (const char *)buf;
    size_t total = 0;
    while (total < len) {
        ssize_t n = send(fd, p + total, len - total, MSG_NOSIGNAL);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        if (n == 0) break;
        total += (size_t)n;
    }
    return (ssize_t)total;
}

int main(int argc, char *argv[]) {
    int port = (argc > 1) ? atoi(argv[1]) : DEFAULT_PORT;
    if (port <= 0 || port > 65535) {
        fprintf(stderr, "Invalid port: %s\n", (argc > 1) ? argv[1] : "N/A");
        return EXIT_FAILURE;
    }

    // Avoid SIGPIPE on send to closed socket (also using MSG_NOSIGNAL)
    signal(SIGPIPE, SIG_IGN);

    int srv = socket(AF_INET, SOCK_STREAM, 0);
    if (srv < 0) {
        perror("socket");
        return EXIT_FAILURE;
    }

    int opt = 1;
    if (setsockopt(srv, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt(SO_REUSEADDR)");
        close(srv);
        return EXIT_FAILURE;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_ANY);
    addr.sin_port = htons((uint16_t)port);

    if (bind(srv, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(srv);
        return EXIT_FAILURE;
    }

    if (listen(srv, BACKLOG) < 0) {
        perror("listen");
        close(srv);
        return EXIT_FAILURE;
    }

    printf("TCP server listening on 0.0.0.0:%d\n", port);

    for (;;) {
        struct sockaddr_in cliaddr;
        socklen_t clilen = sizeof(cliaddr);
        int cli = accept(srv, (struct sockaddr *)&cliaddr, &clilen);
        if (cli < 0) {
            if (errno == EINTR) continue;
            perror("accept");
            break;
        }

        char ipstr[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &cliaddr.sin_addr, ipstr, sizeof(ipstr));
        printf("Client connected: %s:%d\n", ipstr, ntohs(cliaddr.sin_port));

        char buf[BUF_SIZE];
        for (;;) {
            ssize_t n = recv(cli, buf, sizeof(buf), 0);
            if (n < 0) {
                if (errno == EINTR) continue;
                perror("recv");
                break;
            }
            if (n == 0) {
                // Client closed
                break;
            }

            // Echo back
            if (write_all(cli, buf, (size_t)n) < 0) {
                perror("send");
                break;
            }
        }

        printf("Client disconnected: %s:%d\n", ipstr, ntohs(cliaddr.sin_port));
        close(cli);
    }

    close(srv);
    return EXIT_SUCCESS;
}

Build:
- gcc -O2 -Wall -Wextra -o tcp_server tcp_server.c

Run:
- ./tcp_server               (listens on port 8080)
- ./tcp_server 5000          (listens on port 5000)

Test:
- From another terminal: nc 127.0.0.1 8080
- Type anything; the server will echo it back.

Notes:
- To handle multiple clients concurrently, create a thread or fork a process per accepted connection.
- For IPv6 or dual-stack, use getaddrinfo with AF_UNSPEC and bind/listen on results.

